use std::rc::Rc;

struct Owner {
    name: String,
}

struct Gadget {
    id: u32,
    owner: Rc<Owner>,
}

fn main() {
    let owner = Rc::new(Owner { name: String::from("Ada") });
    let g1 = Gadget { id: 1, owner: Rc::clone(&owner) };
    let g2 = Gadget { id: 2, owner: Rc::clone(&owner) };

    println!("gadget {} belongs to {}", g1.id, g1.owner.name);
    println!("gadget {} belongs to {}", g2.id, g2.owner.name);
    println!("owners: {}", Rc::strong_count(&owner));
}

use std::rc::Rc;

fn main() {
    let a = Rc::new(String::from("shared"));
    println!("count after creating a = {}", Rc::strong_count(&a));
    let b = Rc::clone(&a);
    println!("count after creating b = {}", Rc::strong_count(&a));
    {
        let c = Rc::clone(&a);
        println!("count after creating c = {} ({c})", Rc::strong_count(&a));
    }
    println!("count after c goes out of scope = {}", Rc::strong_count(&a));
    println!("{a} {b}");
}

